{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Primary outcomes were all-cause mortality and serious adverse events (as defined by the International Conference on Harmonation-Good Clinical Practice [ICH-GCP] guidelines) [9,16]. Secondary outcomes were admission to intensive care (as defined by trialists), receipt of mechanical ventilation (as defined by trialists), receipt of renal replacement therapy (as defined by trialists), quality of life, and nonserious adverse events. We classified nonserious adverse events as any adverse event not assessed as serious according to the ICH-GCP definition. Wechose to add time to clinical improvement as a post hoc outcome.",
      "reason": "The manuscript lists and defines the primary and secondary outcomes, including definitions for serious and nonserious adverse events and references to trialist definitions for others."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "For all outcomes, we used the trial results reported at maximum follow-up.",
      "reason": "The authors specify a general rule for time frame ('maximum follow-up') for all outcomes, but do not specify the time frame for each individual outcome domain (e.g., mortality at 28 days vs 60 days), though they do mention specific time points in the results sections (e.g., text_30 mentions 15 and 28 days)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly state whether all results compatible with each outcome domain (e.g., all measures, time points, analyses) were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Since the manuscript does not state whether all compatible results were sought, this conditional element cannot be evaluated, but there is no evidence provided that they restricted the search for compatible results."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PRESENT",
      "chunk_id": "text_35",
      "quote": "Further, we included 'time to clinical improvement' as an outcome post hoc.",
      "reason": "The manuscript explicitly reports the addition of 'time to clinical improvement' as a post hoc outcome."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence of changes to the processes for selecting results within eligible outcome domains."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly identify which outcomes were considered most important for interpreting conclusions or provide a rationale for their prioritization."
    }
  ],
  "confidence": 90
}

